class CartFragment : Fragment(R.layout.fragment_cart) {   // supply half
    private val vm: CartViewModel by viewModels()
    override fun onViewCreated(view: View, b: Bundle?) {
        val list = view.findViewById<RecyclerView>(R.id.lines)   // presentational view
        vm.uiState.onEach { list.adapter = CartAdapter(it.lines, vm::remove) }
            .launchIn(viewLifecycleOwner.lifecycleScope)
    }
}
